<script setup>
// Справочник сотрудника: всё, что умеет веб-почта, с точки зрения обычного пользователя (без прав администратора).
// Цифры и адреса приходят с сервера, поиск фильтрует вопросы по тексту.
import { Head, Link } from '@inertiajs/vue3';
import { computed, nextTick, onMounted, ref } from 'vue';
import MailLayout from '../../Layouts/MailLayout.vue';
import Icon from '../../Components/Icon.vue';

const props = defineProps({
    user: String,
    settings: Object,
    domain: String,
    base: String,
    hosts: Object,
    cloud: Object,
    quarantine: Object,
    senders: Object,
    security: Object,
    limits: Object,
});

const SECTIONS = [
    ['start', 'Вход и первые шаги'],
    ['inbox', 'Список писем и поиск'],
    ['read', 'Чтение письма'],
    ['compose', 'Написание письма'],
    ['organize', 'Порядок: папки, метки, отложить'],
    ['rules', 'Правила и автоответ'],
    ['spam', 'Спам, рассылки, карантин'],
    ['shared', 'Общие папки и общие ящики'],
    ['contacts', 'Контакты'],
    ['calendar', 'Календарь и задачи'],
    ['devices', 'Телефон и Outlook'],
    ['security', 'Безопасность'],
    ['shortcuts', 'Горячие клавиши'],
    ['limits', 'Ограничения и цифры'],
    ['trouble', 'Если что-то не так'],
];

const q = ref('');
const root = ref(null);
const shown = ref(0);
const total = ref(0);
let timer = null;

// Поиск: прячем вопросы, в тексте которых нет всех введённых слов; пустые разделы тоже прячем.
function applyFilter() {
    const words = q.value.toLowerCase().split(/\s+/).filter(Boolean);
    const items = root.value?.querySelectorAll('.help__item') || [];
    let n = 0;
    items.forEach((el) => {
        const text = el.textContent.toLowerCase();
        const ok = words.every((w) => text.includes(w));
        el.hidden = !ok;
        if (ok) n++;
    });
    (root.value?.querySelectorAll('.help__section') || []).forEach((s) => {
        s.hidden = words.length > 0 && !s.querySelector('.help__item:not([hidden])');
    });
    shown.value = n;
    total.value = items.length;
}
function onInput() { clearTimeout(timer); timer = setTimeout(applyFilter, 120); }
function clear() { q.value = ''; applyFilter(); }
onMounted(() => { applyFilter(); if (location.hash) nextTick(() => document.getElementById(location.hash.slice(1))?.scrollIntoView()); });

const throttleText = computed(() => {
    const t = props.limits?.throttle;
    if (!t || !t.enabled || !t.maxMsgs) return '';
    const p = t.periodMin === 60 ? 'час' : t.periodMin === 1440 ? 'сутки' : `${t.periodMin} мин`;
    return `${t.maxMsgs} писем в ${p}`;
});
const votesWord = (n) => `не меньше ${n} ${n === 1 ? 'сотрудника' : 'сотрудников'}`;
function printPage() { window.print(); }
</script>

<template>
    <Head title="Справка" />
    <MailLayout :user="user" :theme="settings?.theme">
        <div class="mset help" ref="root">
            <div class="mset__head help__head">
                <Link v-if="user" href="/mail" class="ib" title="К письмам"><Icon name="back" :size="18" /></Link>
                <h1>Справка по почте {{ domain }}</h1>
                <span class="grow" />
                <div class="help__search">
                    <Icon name="search" :size="16" />
                    <input v-model="q" class="input" placeholder="Что вы ищете? Например: отложить, вложение, спам, телефон" @input="onInput">
                    <button v-if="q" class="ib ib--sm" type="button" title="Очистить" @click="clear">✕</button>
                </div>
                <button class="btn btn--sm" type="button" title="Распечатать справочник" @click="printPage"><Icon name="print" :size="14" />Печать</button>
            </div>
            <p v-if="q" class="hint help__count">{{ shown ? `Найдено ответов: ${shown} из ${total}` : 'Ничего не нашлось. Попробуйте другое слово или посмотрите раздел «Если что-то не так».' }}</p>

            <div class="mset__grid">
                <nav class="card mset__menu help__toc">
                    <a v-for="[id, title] in SECTIONS" :key="id" :href="'#' + id">{{ title }}</a>
                </nav>

                <div class="mset__body">
                    <!-- ═══════════ 1. Вход ═══════════ -->
                    <section id="start" class="card mset__section help__section">
                        <h2>Вход и первые шаги</h2>
                        <p class="hint">Веб-почта открывается по адресу <b>{{ base }}/mail</b>. Она же — календарь, контакты и настройки. Всё, что вы делаете здесь, сразу видно в почтовой программе и на телефоне: письма, папки, правила и подпись живут на сервере, а не в браузере.</p>

                        <article class="help__item">
                            <h3>Как войти?</h3>
                            <p>В поле «Адрес или логин» введите свой рабочий адрес целиком (<b>ivanov@{{ domain }}</b>) или только часть до «@». Пароль — тот же, что вы указываете в Outlook или на телефоне. Ни галочки «запомнить меня», ни отдельного пароля для веб-почты нет: вход один для всего.</p>
                        </article>
                        <article class="help__item">
                            <h3>Я забыл пароль или хочу его сменить</h3>
                            <p>Пароль выдаёт и меняет только администратор. В веб-почте нет ни формы «забыли пароль», ни смены пароля в настройках — это сделано намеренно, чтобы никто не мог сменить пароль по чужой ссылке. Напишите или позвоните администратору; после смены пароля обновите его и в почтовых программах.</p>
                        </article>
                        <article class="help__item">
                            <h3>После пароля просят «шесть цифр из приложения» — что это?</h3>
                            <p>У вас включена двухфакторная защита. Откройте приложение-аутентификатор на телефоне (Яндекс Ключ, Google Authenticator или любое другое) и введите код, который оно показывает для «Почта {{ domain }}». Код живёт 30 секунд; если он «не подошёл», проверьте, что время на телефоне выставлено автоматически. Потеряли телефон — только администратор может сбросить защиту.</p>
                        </article>
                        <article class="help__item">
                            <h3>Пишет «Слишком много попыток. Подождите 15 минут»</h3>
                            <p>После восьми неверных паролей подряд с одного адреса вход блокируется на 15 минут — это защита от подбора. Подождите и попробуйте снова. Если вы уверены, что пароль правильный, а войти не выходит — обратитесь к администратору: возможно, пароль уже поменяли.</p>
                        </article>
                        <article class="help__item">
                            <h3>«Вход в веб-почту закрыт администратором» — почта пропала?</h3>
                            <p>Нет. Письма продолжают приходить в ящик, закрыт только вход в веб-интерфейс для вашей учётной записи. Причину уточните у администратора.</p>
                        </article>
                        <article v-if="security.newDevice" class="help__item">
                            <h3>Пришло письмо «Вход в почту с нового устройства»</h3>
                            <p>Так сервер сообщает о входе с браузера или устройства, с которого вы не заходили последние 90 дней. Если это вы — просто закройте письмо. Если нет — откройте Настройки → Безопасность, нажмите «Завершить все, кроме этого» и сразу сообщите администратору, чтобы он сменил пароль.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как переключить тёмную тему?</h3>
                            <p>Кнопка «солнце/луна» на левой полосе переключает тему сразу. В Настройках → Общие можно выбрать «Как в системе» — тогда тема будет следовать за настройкой Windows или телефона.</p>
                        </article>
                        <article class="help__item">
                            <h3>Работает ли с телефона в браузере?</h3>
                            <p>Да. На узком экране список писем и само письмо показываются по очереди, папки открываются кнопкой-«бургером» слева вверху, а круглая кнопка внизу справа — «Написать». Для повседневной работы удобнее всё же подключить встроенную почту телефона — см. раздел «Телефон и Outlook».</p>
                        </article>
                        <article class="help__item">
                            <h3>Что означают иконки на левой полосе?</h3>
                            <p>Сверху вниз: Почта, Календарь, Контакты, Настройки, Справка (эта страница), переключение темы, Выйти. Внизу — ваш аватар с адресом.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 2. Список писем ═══════════ -->
                    <section id="inbox" class="card mset__section help__section">
                        <h2>Список писем и поиск</h2>
                        <article class="help__item">
                            <h3>Какие папки есть с самого начала?</h3>
                            <p><b>Входящие</b>, <b>Отложенные</b> (письма, которые вы отложили «на потом»), <b>Черновики</b>, <b>Отправленные</b>, <b>Архив</b>, <b>Рассылки</b>, <b>Спам</b>, <b>Корзина</b>. Это системные папки: их нельзя переименовать или удалить, но «Спам» и «Корзину» можно очистить правым кликом. Ниже идут «Мои папки» (ваши), «Общие папки» (открытые коллегами), «Метки» и, если есть, «Ждут отправки» и «Карантин».</p>
                            <p>«<b>Важное</b>» — не папка, а выборка: все письма с флажком.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как посмотреть только непрочитанные или только с вложениями?</h3>
                            <p>Над списком есть переключатель «Все · Непрочитанные · Вложения». Он действует внутри текущей папки.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как искать?</h3>
                            <p>Поле «Поиск по письмам» вверху (клавиша <kbd>/</kbd>). Простые слова ищутся по всему письму — заголовкам и тексту. Чтобы сузить, используйте операторы, по-русски или по-английски:</p>
                            <table class="help__table">
                                <tr><td><code>от: иванов</code></td><td>по отправителю (<code>from:</code>)</td></tr>
                                <tr><td><code>кому: sales</code></td><td>по получателю (<code>to:</code>)</td></tr>
                                <tr><td><code>тема: "счёт на оплату"</code></td><td>по теме, фраза в кавычках (<code>subject:</code>)</td></tr>
                                <tr><td><code>копия: petrov</code></td><td>по полю «Копия» (<code>cc:</code>)</td></tr>
                                <tr><td><code>до: 2026-09-01</code></td><td>письма раньше даты (<code>before:</code>)</td></tr>
                                <tr><td><code>после: 2026-08-01</code></td><td>письма позже даты (<code>after:</code>, <code>с:</code>)</td></tr>
                                <tr><td><code>есть: вложение</code></td><td>с вложениями; также <code>есть: флажок</code>, <code>есть: непрочитанное</code>, <code>есть: ответ</code></td></tr>
                            </table>
                            <p>Операторы можно сочетать: <code>от: сибстрой есть: вложение после: 2026-06-01</code>. Поиск идёт по текущей папке. Полнотекстовый индекс на сервере строится в фоне, поэтому письмо, пришедшее секунду назад, может найтись не сразу.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как выделить несколько писем?</h3>
                            <p>Галочка слева в строке; <kbd>Ctrl</kbd>+клик добавляет к выбору, <kbd>Shift</kbd>+клик выделяет диапазон, галочка в шапке списка — все письма на странице. Над списком появится панель «Выбрано N» с действиями: прочитано, непрочитано, в папку, метка, архив, спам, удалить.</p>
                        </article>
                        <article class="help__item">
                            <h3>Можно ли перетаскивать письма?</h3>
                            <p>Да: возьмите строку письма мышью и бросьте на папку в левой колонке. Если выделено несколько — переедут все.</p>
                        </article>
                        <article class="help__item">
                            <h3>Почему в списке только 40 писем?</h3>
                            <p>Список постраничный, по 40 писем. Внизу кнопки «Новее» и «Старее» и номер страницы. Нужное старое письмо быстрее найти поиском, чем листать.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как узнать о новых письмах, не обновляя страницу?</h3>
                            <p>Веб-почта сама проверяет ящик каждые 20 секунд (в фоновой вкладке — раз в минуту) и обновляет список и счётчики. В заголовке вкладки браузера показывается число непрочитанных: «(3) Входящие». Чтобы получать всплывающие уведомления даже при свёрнутом браузере, включите в Настройках → Общие «Уведомления браузера» и разрешите их браузеру.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что показывают кнопки при наведении на письмо?</h3>
                            <p>Архив, Удалить, Флажок и Отложить — те же действия, что в меню, только быстрее. Правый клик по строке открывает полное меню.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 3. Чтение ═══════════ -->
                    <section id="read" class="card mset__section help__section">
                        <h2>Чтение письма</h2>
                        <article class="help__item">
                            <h3>Почему письмо показано как цепочка?</h3>
                            <p>Если вы уже переписывались по этой теме, все письма переписки собираются в одну ленту: заголовок «N в цепочке», старые письма свёрнуты до первых строк, последнее открыто. Клик по шапке письма разворачивает или сворачивает его. У каждого письма в цепочке свои кнопки «Ответить», «Переслать», «Скачать .eml».</p>
                        </article>
                        <article class="help__item">
                            <h3>Вместо картинок плашка «Картинки из интернета скрыты»</h3>
                            <p>Картинки, которые письмо подгружает с чужих сайтов, по умолчанию не загружаются: так отправитель не узнаёт, что вы открыли письмо, и не тратится трафик. Нажмите «Показать», чтобы загрузить их в этом письме. Чтобы показывать всегда, поменяйте в Настройках → Общие «Картинки из интернета в письмах». Вложенные в письмо картинки показываются всегда.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как скачать вложение?</h3>
                            <p>Под текстом письма — плашки с именем и размером файла; клик скачивает. Наведите на плашку, чтобы увидеть тип файла. Если вместо файла в письме список ссылок «Файлы к письму (через облако)» — отправитель отправил большие файлы через облако, откройте ссылку в браузере.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как ответить быстро, не открывая редактор?</h3>
                            <p>Под письмом есть поле «Ответить …» и чипы быстрых ответов («Спасибо, получил.» и др.). Клик по чипу подставляет текст, <kbd>Enter</kbd> отправляет. Свои варианты быстрых ответов задаются в Настройках → Общие (до 8 строк). Кнопка «Открыть полный ответ» переносит набранный текст в обычную форму с форматированием и вложениями.</p>
                        </article>
                        <article class="help__item">
                            <h3>Ответить, ответить всем, переслать</h3>
                            <p>Кнопки над письмом или клавиши <kbd>r</kbd>, <kbd>a</kbd>, <kbd>f</kbd>. При ответе исходный текст подставляется цитатой, при пересылке — блок «Пересланное письмо» с полями От/Дата/Тема/Кому. Вложения при пересылке уходят вместе с письмом; при ответе их можно включить тумблером «Вложения исходного письма» в панели редактора. Если в Настройках включено «По умолчанию отвечать всем», клавиша <kbd>r</kbd> будет отвечать всем.</p>
                        </article>
                        <article class="help__item">
                            <h3>Кнопка «Встреча» над письмом</h3>
                            <p>Создаёт событие в календаре по этому письму: тема письма станет названием, все участники переписки — приглашёнными, начало текста — описанием. Останется выбрать время и нажать «Сохранить и пригласить».</p>
                        </article>
                        <article class="help__item">
                            <h3>Как распечатать письмо или сохранить его файлом?</h3>
                            <p>«Печать» — кнопка справа над письмом. «Скачать .eml» (меню «Ещё» или кнопка в шапке письма) сохраняет письмо целиком, со всеми вложениями и заголовками, — такой файл открывается Outlook и Thunderbird. «Показать оригинал» открывает исходный текст письма в новой вкладке — пригодится, если администратор попросит заголовки.</p>
                        </article>
                        <article class="help__item">
                            <h3>Кнопка «Отписаться от рассылки»</h3>
                            <p>Появляется под письмами, у которых есть служебный адрес отписки. Клик либо открывает страницу отписки на сайте отправителя, либо готовит письмо «Unsubscribe» — его нужно отправить. Это честная отписка по правилам рассылок; если отправитель не уважает её, пометьте письмо как спам или рассылку (см. раздел «Спам, рассылки, карантин»).</p>
                        </article>
                        <article class="help__item">
                            <h3>Что означает иконка стрелки в строке письма?</h3>
                            <p>«Вы ответили» — на это письмо уже есть ваш ответ. Флажок — письмо отмечено как важное. Скрепка — есть вложения. Цветные точки — метки.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 4. Написание ═══════════ -->
                    <section id="compose" class="card mset__section help__section">
                        <h2>Написание письма</h2>
                        <article class="help__item">
                            <h3>Как указать получателей?</h3>
                            <p>Начните печатать имя или адрес в поле «Кому» — с первой буквы появятся подсказки: коллеги («рабочая почта»), их личные адреса, если администратор их указал («личная почта сотрудника»), адреса из вашей переписки («из переписки») и контакты из книг. Выбирайте стрелками и <kbd>Enter</kbd>. Несколько адресов разделяйте запятой, точкой с запятой или <kbd>Enter</kbd>. Можно вставить целый список адресов из буфера — он разобьётся сам. Ссылки «Копия» и «Скрытая» справа открывают соответствующие строки. Адрес с ошибкой подсвечивается красным, и письмо не отправится, пока вы его не исправите.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что за строка «От кого» и почему её иногда нет?</h3>
                            <p>Она появляется, только если вам есть из чего выбирать: администратор назначил вам дополнительные адреса (псевдонимы) или коллега открыл вам свой ящик как редактору. Отправлять можно только с адресов вашей компании; резервная личная почта, указанная в карточке сотрудника, отправителем быть не может — это адрес для связи, а не ящик.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что умеет редактор?</h3>
                            <p>Жирный (<kbd>Ctrl</kbd>+<kbd>B</kbd>), курсив (<kbd>Ctrl</kbd>+<kbd>I</kbd>), подчёркнутый (<kbd>Ctrl</kbd>+<kbd>U</kbd>), ссылка (<kbd>Ctrl</kbd>+<kbd>K</kbd>), маркированный и нумерованный списки, цитата, «Убрать форматирование». Вставка из Word и с сайтов всегда идёт чистым текстом: чужие стили ломают вид письма у получателя. Проверка орфографии — браузерная. <kbd>Ctrl</kbd>+<kbd>Enter</kbd> отправляет, <kbd>Ctrl</kbd>+<kbd>S</kbd> сохраняет черновик.</p>
                        </article>
                        <article class="help__item">
                            <h3>Подпись</h3>
                            <p>Настройки → Подпись: редактор с форматированием (имя, должность, телефон). В новых письмах подпись подставляется всегда, в ответах и пересылках — если включён тумблер «Добавлять подпись в ответах и пересылках».</p>
                        </article>
                        <article class="help__item">
                            <h3>Как приложить файлы и какие есть ограничения?</h3>
                            <p>Кнопка «Вложить файл» (скрепка) или перетащите файлы в окно письма. За раз — до 20 файлов. Общий размер письма с вложениями не должен превышать <b>{{ limits.sizeLimitMb }} МБ</b>: больше сервер не пропустит, а многие получатели не примут и 20 МБ — веб-почта предупредит, если письмо получается тяжёлым. Файлы с расширениями <b>{{ limits.blockedExt || 'exe, scr, bat, cmd, js, vbs, pif' }}</b> сервер режет как опасные — и у вас, и у получателя; заархивируйте их в zip с паролем и сообщите пароль отдельно.</p>
                        </article>
                        <article v-if="cloud.enabled" class="help__item">
                            <h3>Как отправить большой файл?</h3>
                            <p>Файлы размером от <b>{{ cloud.thresholdMb }} МБ</b> веб-почта автоматически помечает облачком: при отправке они загружаются в корпоративное облако, а в письмо вставляется список ссылок «Файлы к письму (через облако)». Получатель скачивает файл по ссылке; ссылки действуют <b>{{ cloud.expireDays ? cloud.expireDays + ' дн.' : 'бессрочно' }}</b>. Любой файл можно переключить вручную: кнопка на плашке файла «Отправить ссылкой через облако» / «Вложить в письмо». Максимальный размер одного файла для облака — 256 МБ. Файлы, отправленные через облако, в «Отправленных» хранятся ссылками, а не копией.</p>
                        </article>
                        <article v-else class="help__item">
                            <h3>Как отправить большой файл?</h3>
                            <p>Отправка через облако сейчас не подключена, поэтому действует только лимит письма — {{ limits.sizeLimitMb }} МБ. Большие файлы передавайте через корпоративное файловое хранилище, а в письмо вставляйте ссылку.</p>
                        </article>
                        <article class="help__item">
                            <h3>Черновики</h3>
                            <p>Письмо сохраняется в «Черновики» само каждые 30 секунд и при закрытии формы (крестик «Закрыть (черновик сохранится)»). Статус «Черновик сохранён 12:41» виден внизу формы. Открыть черновик — папка «Черновики», кнопка «Продолжить черновик». Удалить — красная кнопка «Удалить черновик и закрыть». Черновики видны и в почтовых программах.</p>
                        </article>
                        <article class="help__item">
                            <h3>Я нажал «Отправить» и передумал</h3>
                            <p>После отправки внизу появляется плашка «Письмо отправлено — Отменить» с обратным отсчётом. По умолчанию 5 секунд; в Настройках → Общие → «Отмена отправки» можно поставить 10, 20 или 30 секунд либо выключить. Пока отсчёт идёт, письмо ещё не ушло; после — отозвать его нельзя.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как отправить письмо позже, в назначенное время?</h3>
                            <p>Кнопка с часами рядом с «Отправить» → «Отправить позже»: «Сегодня вечером 18:00», «Завтра утром 09:00», «В понедельник 09:00», «Через неделю» или своё время. Письмо попадает в очередь «Ждут отправки» (пункт появится в левой колонке) и уйдёт с сервера в указанное время, даже если браузер закрыт. Передумали — откройте «Ждут отправки» и нажмите «Отменить»: письмо вернётся в черновики.</p>
                        </article>
                        <article class="help__item">
                            <h3>«Напомнить, если не ответят» — как это работает?</h3>
                            <p>Кнопка с колокольчиком в форме письма (или пункт «Ещё → Напомнить, если не ответят…» у уже полученного письма). Выберите срок: 1, 2, 3, 5 или 7 дней. Если за это время на письмо не придёт ответ, оно вернётся во «Входящие» непрочитанным и с флажком, чтобы вы не забыли переспросить. Ответ пришёл — напоминание отменяется само.</p>
                        </article>
                        <article class="help__item">
                            <h3>Важность и уведомление о прочтении</h3>
                            <p>Кнопка «Ещё» (⋯) в форме: «Пометить как важное» ставит высокую важность (получатель увидит восклицательный знак), «Запросить уведомление о прочтении» просит почтовую программу получателя сообщить об открытии письма. Ответит ли она — решает получатель; веб-почта таких запросов не показывает и не отвечает на них автоматически.</p>
                        </article>
                        <article class="help__item">
                            <h3>Письмо без темы</h3>
                            <p>Отправить можно, но веб-почта переспросит: «Отправить письмо без темы?». Лучше тему указывать: письма без темы чаще попадают в спам у получателей.</p>
                        </article>
                        <article class="help__item">
                            <h3>Сколько писем и кому можно отправить?</h3>
                            <p>В одном письме — до {{ limits.maxRecipients }} получателей.<template v-if="throttleText"> Общий лимит исходящих для каждого сотрудника — {{ throttleText }}; при превышении сервер откладывает отправку, а не теряет письмо.</template> Для массовых рассылок клиентам используйте рассылки, которые создаёт администратор, а не поле «Скрытая».</p>
                        </article>
                    </section>

                    <!-- ═══════════ 5. Порядок ═══════════ -->
                    <section id="organize" class="card mset__section help__section">
                        <h2>Порядок: папки, метки, отложить</h2>
                        <article class="help__item">
                            <h3>Как создать папку, в том числе вложенную?</h3>
                            <p>Кнопка «+» у заголовка «Мои папки», пункт «Новая папка…» в меню «В папку» или правый клик по своей папке → «Вложенная папка…». Название — любое, кроме пустого; символы «/» и «.» заменятся на пробел. Папки можно переименовывать и удалять правым кликом (удаление стирает и письма в ней — веб-почта покажет, сколько). Всё это же есть в Настройках → Папки и метки. Папки создаются на сервере и появятся в Outlook и на телефоне.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как переместить письмо в папку?</h3>
                            <p>Перетащите его на папку, или правый клик → «В папку» (клавиша <kbd>v</kbd>), или панель массовых действий при выделении. «Архив» (<kbd>e</kbd>) — быстрое перемещение в папку «Архив»: письмо уходит из «Входящих», но остаётся в поиске.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что такое метки и чем они отличаются от папок?</h3>
                            <p>Письмо лежит в одной папке, а меток у него может быть несколько («Срочно», «Клиенты», «Ждёт оплаты»). Создать метку: «+» у заголовка «Метки», выбрать цвет из семи. Поставить: правый клик по письму → «Метка» (<kbd>l</kbd>). Клик по метке в левой колонке показывает все письма с ней. Правый клик по метке — сменить цвет, переименовать, удалить (письма останутся). Метки хранятся в самом ящике, поэтому их видят почтовые программы, которые умеют ключевые слова IMAP, например Thunderbird.</p>
                        </article>
                        <article class="help__item">
                            <h3>Флажок и папка «Важное»</h3>
                            <p>Флажок (<kbd>s</kbd> или иконка при наведении) отмечает письмо как важное. «Важное» в левой колонке собирает все такие письма из «Входящих». В Outlook и на телефоне флажок виден как «отмеченное» письмо.</p>
                        </article>
                        <article class="help__item">
                            <h3>«Отложить до…» — что происходит с письмом?</h3>
                            <p>Письмо убирается из «Входящих» в папку «Отложенные» и в назначенный срок возвращается обратно — непрочитанным и с флажком. Варианты: «Сегодня вечером 18:00» (если ещё нет 17:00), «Завтра утром 09:00», «В понедельник 09:00», «Через неделю» или своё время. Передумали — откройте «Отложенные» и выберите «Вернуть во Входящие». Отложить можно только письма со служебным идентификатором Message-ID; у редких писем его нет, тогда веб-почта скажет об этом.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как удалить письмо навсегда?</h3>
                            <p>Удаление переносит письмо в «Корзину». Удаление из «Корзины» («Удалить навсегда») или «Очистить…» правым кликом по «Корзине» стирает окончательно. Восстановить стёртое письмо можно только из резервной копии сервера — через администратора и не всегда.</p>
                        </article>
                        <article class="help__item">
                            <h3>Сколько места у меня в ящике?</h3>
                            <p>Внизу левой колонки — полоска «Занято X из Y». Когда ящик заполнен, новые письма перестают приходить, а отправители получают отказ. Чистите «Корзину» и «Спам», удаляйте письма с тяжёлыми вложениями или попросите администратора увеличить квоту.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 6. Правила ═══════════ -->
                    <section id="rules" class="card mset__section help__section">
                        <h2>Правила и автоответ</h2>
                        <article class="help__item">
                            <h3>Что такое правила и где они выполняются?</h3>
                            <p>Правило — это «если письмо такое-то, сделать то-то». Правила выполняются на сервере в момент получения письма, поэтому работают и когда веб-почта закрыта, и для Outlook, и для телефона. Настройки → Правила → «Новое правило».</p>
                        </article>
                        <article class="help__item">
                            <h3>Какие бывают условия и действия?</h3>
                            <p><b>Условия:</b> Отправитель, Получатель, Кому или копия, Тема, Текст письма, Заголовок (любой служебный, например X-Priority), Размер в КБ. Операторы: содержит, не содержит, равно, начинается с, заканчивается на; для размера — больше/меньше. Несколько условий объединяются «выполнены все» или «выполнено любое».</p>
                            <p><b>Действия:</b> переместить в папку, копию в папку, поставить метку, флажок, пометить прочитанным, переслать на адрес, переслать копию (письмо остаётся и у вас), удалить, ответить текстом, остановить обработку. Тумблер «Не применять следующие правила к этому письму» полезен, когда правила пересекаются.</p>
                            <p>Пример: «Отправитель содержит @sibstroy.ru» → «Переместить в папку Клиенты/Сибстрой» и «Поставить метку Клиенты».</p>
                        </article>
                        <article class="help__item">
                            <h3>В каком порядке работают правила?</h3>
                            <p>Сверху вниз, как в списке. Кнопки «Выше»/«Ниже» меняют порядок. Правила, созданные из меню «Спам»/«Рассылка», встают в начало списка. Правило можно временно выключить тумблером, не удаляя. Лимит — 50 правил, по 10 условий и 6 действий в каждом.</p>
                        </article>
                        <article class="help__item">
                            <h3>Правила действуют только на новые письма. А старые?</h3>
                            <p>Кнопка «Разложить Входящие» в разделе Правила прогоняет все ваши правила по письмам, которые уже лежат во «Входящих». Для старой почты применяются условия по отправителю, получателю, теме и заголовку и действия «папка», «копия», «метка», «флажок», «прочитано», «удалить»; условия по тексту письма и размеру, пересылка и автоответ к старым письмам не применяются — веб-почта перечислит, что пропустила. По окончании покажется, сколько писем обработано каждым правилом.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как включить автоответ на время отпуска?</h3>
                            <p>Настройки → Автоответ: тумблер «Включён», даты «С» и «По» (можно не указывать — тогда работает, пока не выключите), тема и текст, частота «Отвечать одному адресу не чаще, чем раз в день / 3 дня / неделю». Автоответ работает на сервере и не отвечает рассылкам и спаму. Не забудьте, что автоответ уходит всем, включая внешних отправителей, — не пишите в нём лишнего.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как настроить пересылку своей почты на другой адрес?</h3>
                            <p>Правилом «любое письмо → Переслать копию на адрес». Учтите, что пересылка рабочей почты на личные ящики может быть запрещена правилами компании — уточните у администратора. Постоянную пересылку и дополнительные адреса администратор настраивает в вашей карточке.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 7. Спам ═══════════ -->
                    <section id="spam" class="card mset__section help__section">
                        <h2>Спам, рассылки, карантин</h2>
                        <article class="help__item">
                            <h3>Как сервер решает, что письмо — спам?</h3>
                            <p>Каждое входящее письмо получает оценку. Подозрительные письма кладутся в папку «Спам» с пометкой в теме, откровенный спам и письма с вирусами или опасными вложениями — в карантин, откуда вы их можете достать сами. Фильтр учится: чем больше сотрудники помечают письма, тем точнее он работает.</p>
                        </article>
                        <article class="help__item">
                            <h3>Письмо попало в «Спам», а оно нужное</h3>
                            <p>Правый клик → «Не спам». Письмо вернётся во «Входящие», а фильтр запомнит его как хорошее. Затем веб-почта спросит, добавить ли отправителя в исключения — «Адрес» или «Весь домен». <template v-if="senders.hamGlobal">Исключение действует для всей компании: сервер перестаёт считать письма с этого адреса или домена спамом у всех сотрудников.</template> Старые письма этого отправителя из «Спама» тоже вернутся во «Входящие». Если добавлять ничего не хотите — «Только это письмо».</p>
                        </article>
                        <article class="help__item">
                            <h3>Как пометить письмо как спам, чтобы такие больше не приходили?</h3>
                            <p>Правый клик → «Спам» (клавиша <kbd>!</kbd>). Письмо уедет в «Спам», а фильтр обучится на нём. Затем появится вопрос: «Все письма с адреса …» или «Все письма с домена @…». Выберите — и у вас появится личное правило (Настройки → Правила): всё от этого отправителя будет сразу уходить в «Спам». Тумблер «Сразу разложить уже полученные письма по всем папкам» найдёт письма этого отправителя во всех ваших папках и переложит их в «Спам».</p>
                            <p>Как только одинаково отметят {{ votesWord(senders.spamVotes) }}, правило станет общим для всех ящиков компании — веб-почта сообщит об этом. Свой домен пометить спамом нельзя.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что такое «Рассылка» и папка «Рассылки»?</h3>
                            <p>Не спам, но и не деловая переписка: новости магазинов, уведомления сервисов, дайджесты. Правый клик → «Рассылка»: письмо уедет в папку «Рассылки», и веб-почта предложит отправлять туда всё от этого адреса или домена — сразу и старые письма тоже. Это личное правило; общим для всех оно становится, когда одинаково отметят {{ votesWord(senders.listsVotes) }}. «Рассылки» — обычная папка, письма в ней остаются и ищутся.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что такое карантин и где он?</h3>
                            <p>Пункт «Карантин» в левой колонке (со счётчиком) или адрес <b>{{ base }}/mail/quarantine</b>. Здесь письма, которые сервер посчитал явным спамом, вирусом или опасным вложением и не положил даже в «Спам». У каждого — отправитель, тема, причина («спам 15.4», «вирус», «вложение») и кнопки «Доставить» и «Удалить». «Доставить» кладёт письмо во «Входящие» как обычное и предлагает добавить отправителя в исключения. Карантин чистится сам через {{ quarantine.keepDays }} дней.</p>
                        </article>
                        <article v-if="quarantine.digest" class="help__item">
                            <h3>Письмо «В карантине N писем за сутки»</h3>
                            <p>Ежедневная сводка (около {{ quarantine.digestTime }}) от noreply@{{ domain }}: список задержанных писем с темами и ссылками «Доставить». Ссылка работает без входа в течение 7 дней и доставляет письмо во «Входящие». Если писем в карантине не было, сводка не приходит.</p>
                        </article>
                        <article class="help__item">
                            <h3>Мне не приходит письмо, отправитель говорит, что отправил</h3>
                            <p>Проверьте по порядку: папку «Спам», «Карантин», папку «Рассылки», не сработало ли ваше правило (Настройки → Правила), не переполнен ли ящик (полоска внизу слева). Поиск «от: адрес» по всем папкам тоже помогает. Если нигде нет — сообщите администратору адрес отправителя и примерное время: он посмотрит журнал сервера.</p>
                        </article>
                        <article class="help__item">
                            <h3>Вложение «вырезано» или письмо с .exe не пришло</h3>
                            <p>Исполняемые файлы ({{ limits.blockedExt || 'exe, scr, bat, cmd, js, vbs, pif' }}) сервер блокирует и у входящих, и у исходящих писем — так распространяются вирусы. Попросите отправителя упаковать файл в zip с паролем. Заражённые вложения удаляются антивирусом, письмо попадает в карантин с пометкой «вирус».</p>
                        </article>
                    </section>

                    <!-- ═══════════ 8. Общие папки ═══════════ -->
                    <section id="shared" class="card mset__section help__section">
                        <h2>Общие папки и общие ящики</h2>
                        <article class="help__item">
                            <h3>Как открыть коллеге доступ к своей папке или к «Входящим»?</h3>
                            <p>Правый клик по папке → «Общий доступ…». Выберите сотрудника и уровень: <b>читатель</b> только смотрит письма и может помечать их прочитанными; <b>редактор</b> ещё перекладывает, удаляет и добавляет письма. Доступ можно менять и закрывать в том же окне. Доступ к «Входящим» открывает только сами «Входящие»; на каждую вложенную папку доступ выдаётся отдельно.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как выглядит чужая папка у меня?</h3>
                            <p>В левой колонке в группе «Общие папки» появится имя владельца, а под ним — папки, которые он открыл. Работать с ними можно как со своими, в пределах выданных прав; правый клик подскажет: «доступ настраивает владелец». Общие папки видны и в Outlook/Thunderbird (там они обычно в разделе «Shared» или «Общие»).</p>
                        </article>
                        <article class="help__item">
                            <h3>Общие ящики отделов (info@, sales@, buh@)</h3>
                            <p>Такие ящики создаёт администратор и открывает к ним доступ нужным сотрудникам. Дальше всё как с обычной общей папкой: ящик виден в «Общих папках». Если у вас права редактора на «Входящие» общего ящика, вы можете и отвечать от его имени.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как отправить письмо от имени общего ящика?</h3>
                            <p>В форме письма в строке «От кого» выберите «info@… — общий ящик «Имя»». Такие пункты появляются только у редакторов «Входящих» этого ящика. Получатель увидит письмо от общего адреса, копия ляжет в «Отправленные» самого общего ящика, чтобы её видели все, кто с ним работает. Читателям отправка от имени ящика недоступна.</p>
                        </article>
                        <article class="help__item">
                            <h3>Можно ли открыть папку «всем» или отделу разом?</h3>
                            <p>Доступ выдаётся поимённо. Для папок, которыми пользуется весь отдел, удобнее попросить администратора создать общий ящик отдела и открыть его нужным людям.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 9. Контакты ═══════════ -->
                    <section id="contacts" class="card mset__section help__section">
                        <h2>Контакты</h2>
                        <article class="help__item">
                            <h3>Какие книги есть и кто что может?</h3>
                            <p><b>Мои контакты</b> — ваша личная книга, полный доступ. <b>Отдел «…»</b> — книга вашего подразделения: видят все его сотрудники, правит администратор. <b>Сотрудники</b> — все коллеги с рабочими адресами и телефонами, заполняет администратор. <b>Контакты компании</b> — общая книга контрагентов, правит администратор, а вы можете предложить в неё контакт. Общие книги только для чтения: у контакта из них вместо «Изменить» кнопка «К себе» — скопировать в свою книгу и править копию.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как добавить контакт?</h3>
                            <p>«Новый контакт» (клавиша <kbd>n</kbd>): фамилия, имя, отчество, организация, должность, несколько адресов почты (рабочая/личная/другая) и телефонов (мобильный/рабочий/домашний/факс), почтовый адрес, день рождения, сайт, группы через запятую, заметка, фото до 1,5 МБ, галочка «В избранные». Контакт появится и на телефоне, если подключены контакты по CardDAV.</p>
                        </article>
                        <article class="help__item">
                            <h3>«История общения» — что это?</h3>
                            <p>Список адресов, с которыми вы переписывались, но которых нет ни в одной книге: кто, сколько писем, когда последнее. «Добавить в мои контакты» открывает форму с уже заполненными именем и адресом; «Убрать из истории» скрывает адрес из списка. Эти же адреса подсказываются в поле «Кому» как «из переписки».</p>
                        </article>
                        <article class="help__item">
                            <h3>Как предложить контакт в общую книгу компании?</h3>
                            <p>Сначала контакт должен быть в ваших «Моих контактах». Откройте его и нажмите «В общую» (или правый клик → «Предложить в общую»). Заявка уходит администратору; после одобрения контакт появится в «Контактах компании» у всех. Если тот же адрес уже предложил другой сотрудник, второе предложение подтверждает первое, и контакт добавляется сразу. Если адрес уже есть в общей книге, веб-почта так и скажет.</p>
                        </article>
                        <article class="help__item">
                            <h3>Группы и избранные</h3>
                            <p>Группы — это категории из поля «Группы» карточки («Клиенты, Поставщики»); они собраны в левой колонке, клик показывает всех участников. Избранные — звёздочка в карточке или в меню; отметить избранным можно только контакт из своей книги (чужой сначала скопируйте «К себе»).</p>
                        </article>
                        <article class="help__item">
                            <h3>Импорт и экспорт</h3>
                            <p>Кнопки внизу левой колонки. Импорт принимает файлы .vcf (vCard) до 10 МБ — так переносят контакты из телефона, Outlook или старой почты. Экспорт выгружает текущую книгу (или все) в .vcf.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как написать или назначить встречу контакту?</h3>
                            <p>В карточке кнопки «Написать» и «Встреча»; клик по адресу почты тоже открывает письмо, по телефону — набор номера, если на компьютере есть телефония. Правый клик по строке контакта даёт то же меню.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 10. Календарь ═══════════ -->
                    <section id="calendar" class="card mset__section help__section">
                        <h2>Календарь и задачи</h2>
                        <article class="help__item">
                            <h3>Виды и навигация</h3>
                            <p>«День · Неделя · Месяц · Повестка» (повестка — список на 30 дней вперёд), «Сегодня», стрелки назад/вперёд, мини-календарь слева. Клавиши: <kbd>c</kbd> — новое событие, <kbd>t</kbd> — сегодня, <kbd>←</kbd>/<kbd>→</kbd> — период, <kbd>d</kbd> <kbd>w</kbd> <kbd>m</kbd> <kbd>a</kbd> — переключение видов. Клик по пустому месту сетки создаёт событие на это время, клик по строке «весь день» — событие на весь день.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как создать событие и пригласить коллег?</h3>
                            <p>Кнопка «Событие»: название, «Весь день» или начало и окончание, повтор (день/неделя/месяц/год, до даты), напоминание (от «в момент начала» до «за 2 дня», по умолчанию за 15 минут), место, календарь, участники, описание, галочка «Не показывать меня занятым». Как только вы добавляете участников, ниже появляется полоса «Занятость» — видно, кто из коллег в это время уже занят («занято: N»). Кнопка «Сохранить и пригласить» отправит каждому участнику письмо с приглашением; внешним адресам — обычное письмо с файлом .ics, который открывается в любом календаре.</p>
                        </article>
                        <article class="help__item">
                            <h3>Мне пришло приглашение — как ответить?</h3>
                            <p>Откройте событие в календаре (оно появится там автоматически) — в блоке «Ваш ответ на приглашение» кнопки «Принять», «Под вопросом», «Отклонить». Организатор увидит ваш ответ в списке участников события. Если приглашение пришло письмом от внешнего организатора, откройте вложение .ics — событие добавится в календарь.</p>
                        </article>
                        <article class="help__item">
                            <h3>Напоминания</h3>
                            <p>Напоминание из события приходит тремя путями: всплывающим уведомлением в веб-почте (если вкладка открыта и уведомления включены), письмом от «Календарь {{ domain }}» с темой «Напоминание: …» и на телефон — если календарь подключён по CalDAV, телефон напомнит сам. Письмо уходит один раз на каждое напоминание.</p>
                        </article>
                        <article class="help__item">
                            <h3>Повторяющиеся события</h3>
                            <p>Поле «Повтор» + «До даты». При удалении повторяющегося события веб-почта спросит: «Только это вхождение» или «Все повторы». Участники при удалении события с приглашениями получают отмену.</p>
                        </article>
                        <article class="help__item">
                            <h3>Свои календари и общий доступ</h3>
                            <p>«Новый календарь» в левой колонке — например, «Проекты» или «Отпуска». Правый клик по календарю: цвет, «Общий доступ…» (сотрудник и уровень «только чтение» / «чтение и правка»), переименовать, «Скачать .ics», удалить. Открытые вам календари коллег появятся в группе «Общие» с именем владельца; от чужого календаря можно «Отписаться». Занятость по вашему календарю коллеги видят и без общего доступа — при планировании встреч, без названий событий.</p>
                        </article>
                        <article class="help__item">
                            <h3>Календарь отдела и календарь компании</h3>
                            <p>Календарь вашего подразделения виден всем его сотрудникам; кто в нём может создавать события, определяет администратор. «Календарь компании» (праздники, общие мероприятия) ведёт администратор, у сотрудников он только для чтения.</p>
                        </article>
                        <article class="help__item">
                            <h3>Задачи</h3>
                            <p>Группа «Задачи» в левой колонке календаря: введите текст в поле «Новая задача…», при желании срок, и нажмите <kbd>Enter</kbd>. Галочка закрывает задачу, «Показать выполненные» показывает закрытые, клик по задаче открывает правку (название, срок, важность, заметка). Просроченные подсвечены. Задачи хранятся в вашем календаре и синхронизируются с приложениями задач по CalDAV (например, Tasks.org на Android, «Напоминания» на iPhone).</p>
                        </article>
                    </section>

                    <!-- ═══════════ 11. Устройства ═══════════ -->
                    <section id="devices" class="card mset__section help__section">
                        <h2>Телефон и Outlook</h2>
                        <p class="hint">Все параметры собраны в Настройках → Безопасность → «Подключение почтовых программ». Логин везде — ваш полный адрес, пароль — от почты или пароль приложения.</p>
                        <article class="help__item">
                            <h3>Параметры подключения</h3>
                            <table class="help__table">
                                <tr><td>Входящие (IMAP)</td><td><code>{{ hosts.imap }}</code>, порт 993, SSL/TLS</td></tr>
                                <tr><td>Исходящие (SMTP)</td><td><code>{{ hosts.smtp }}</code>, порт 465 (SSL) или 587 (STARTTLS), с авторизацией тем же логином и паролем</td></tr>
                                <tr><td>Календарь и контакты (CalDAV/CardDAV)</td><td><code>{{ hosts.dav }}</code></td></tr>
                                <tr><td>Логин</td><td>полный адрес, например ivanov@{{ domain }}</td></tr>
                            </table>
                            <p>POP3 не используйте: он скачивает письма на одно устройство и не показывает папки.</p>
                        </article>
                        <article class="help__item">
                            <h3>iPhone, iPad, Mac</h3>
                            <p>Самый простой способ — профиль: откройте в Safari на устройстве ссылку <a :href="hosts.mobileconfig">{{ hosts.mobileconfig }}</a>, установите профиль (Настройки → Профиль загружен) и введите пароль. Профиль настраивает сразу почту, контакты и календарь. Вручную: «Другая» учётная запись → Почта с параметрами из таблицы; затем отдельно учётные записи CalDAV и CardDAV с сервером <code>{{ base.replace('https://', '') }}</code>.</p>
                        </article>
                        <article class="help__item">
                            <h3>Android</h3>
                            <p>Почта: Gmail или любая почтовая программа → добавить учётную запись → «Другая» → IMAP; обычно достаточно ввести адрес и пароль, параметры программа найдёт сама. Контакты и календарь: бесплатное приложение DAVx⁵ (есть в Google Play и F-Droid) → «Вход с URL» → адрес <code>{{ hosts.dav }}</code>, логин и пароль; после этого отметьте в DAVx⁵ книги и календари, которые хотите видеть на телефоне. Задачи — приложение Tasks.org через тот же DAVx⁵.</p>
                        </article>
                        <article class="help__item">
                            <h3>Outlook</h3>
                            <p><b>Почта.</b> Классический Outlook находит настройки сам: добавьте учётную запись, введите адрес и пароль. Если спрашивает тип — IMAP с параметрами из таблицы. Новый Outlook (Windows 11) также подключает почту по IMAP.</p>
                            <p><b>Календарь и контакты.</b> Классический Outlook сам не умеет CalDAV/CardDAV — поставьте бесплатный «Outlook CalDav Synchronizer» и укажите в нём адрес <code>{{ hosts.dav }}</code>, логин и пароль. После синхронизации ваш календарь и книги появятся в Outlook. Новый Outlook такие дополнения не поддерживает: календарём и контактами в нём пользуйтесь через веб-почту.</p>
                        </article>
                        <article class="help__item">
                            <h3>Thunderbird и другие программы</h3>
                            <p>Thunderbird находит настройки автоматически по адресу; календарь и контакты подключаются встроенными средствами по адресу <code>{{ hosts.dav }}</code>. Программы, которые не умеют автонастройку, настраивайте по таблице выше.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что синхронизируется, а что нет?</h3>
                            <p>Синхронизируются письма, папки, флажки, черновики, отправленные, общие папки, контакты, календари, задачи. Правила, автоответ и подпись живут на сервере и в веб-почте — программе их настраивать не нужно (правила сработают до того, как письмо дойдёт до программы). Метки видят только программы с поддержкой ключевых слов IMAP. «Отложенные» и «Ждут отправки» — функции веб-почты: в программе они видны как обычные папки.</p>
                        </article>
                        <article v-if="security.appPasswords" class="help__item">
                            <h3>Зачем пароль приложения и как его сделать?</h3>
                            <p>Отдельный пароль для каждого устройства: если телефон потеряется, отзовите только его пароль — основной менять не придётся. Обязателен, если у вас включена двухфакторная защита (телефон и Outlook не умеют вводить код). Настройки → Безопасность → «Пароли приложений» → «Создать»: назовите («iPhone», «Outlook дома»), подтвердите своим паролем — и скопируйте показанный пароль сразу: второй раз он не покажется. Можно создать до 10 паролей; «Отозвать» отключает устройство.</p>
                        </article>
                    </section>

                    <!-- ═══════════ 12. Безопасность ═══════════ -->
                    <section id="security" class="card mset__section help__section">
                        <h2>Безопасность</h2>
                        <article class="help__item">
                            <h3>Как включить двухфакторную защиту?</h3>
                            <p>Настройки → Безопасность → «Подключить приложение»: отсканируйте QR-код приложением-аутентификатором (или введите ключ вручную), введите шесть цифр — готово. С этого момента при входе в веб-почту после пароля будут спрашивать код. Почтовые программы и телефон при включённой защите подключайте паролем приложения. Выключить — в том же разделе, введя пароль от почты; если защиту требует администратор, выключить нельзя.</p>
                        </article>
                        <article class="help__item">
                            <h3>«Администратор требует двухфакторную защиту»</h3>
                            <p>Плашка появляется после входа, если для вас включено требование. Подключите приложение по шагам выше — почта откроется сразу после этого.</p>
                        </article>
                        <article class="help__item">
                            <h3>Где посмотреть, кто входил в мою почту?</h3>
                            <p>Настройки → Безопасность → «Где вы вошли»: список активных сеансов (устройство, адрес, когда) с кнопкой «Завершить» у каждого и «Завершить все, кроме этого». Ниже «Последние входы»: дата, устройство, результат («вход», «вход с нового устройства», «неверный пароль», «неверный код», «заблокировано»). Незнакомые записи — повод сразу завершить чужие сеансы и сообщить администратору.</p>
                        </article>
                        <article class="help__item">
                            <h3>Кажется, мой пароль узнали</h3>
                            <p>1) Настройки → Безопасность → «Завершить все, кроме этого». 2) Отзовите пароли приложений, которые не узнаёте. 3) Сообщите администратору — сменить пароль может только он. 4) После смены обновите пароль в своих программах и на телефоне.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как отличить фишинг?</h3>
                            <p>Сервер помечает подделки, но не все. Насторожитесь, если письмо требует срочно «подтвердить пароль», «оплатить счёт по новым реквизитам», ссылка ведёт не на тот домен, что написан, или вложение — архив с «документом». Веб-почта никогда не просит пароль ссылкой из письма: пароль меняет только администратор лично. Сомневаетесь — не открывайте вложение, пометьте письмо как спам и спросите администратора.</p>
                        </article>
                        <article class="help__item">
                            <h3>Выход из веб-почты</h3>
                            <p>Кнопка «Выйти» внизу левой полосы. На чужом компьютере обязательно выходите: сессия иначе живёт, пока её не закрыть. Проверить и закрыть забытые сессии можно из «Где вы вошли».</p>
                        </article>
                    </section>

                    <!-- ═══════════ 13. Клавиши ═══════════ -->
                    <section id="shortcuts" class="card mset__section help__section">
                        <h2>Горячие клавиши</h2>
                        <p class="hint">Работают в списке писем, когда не открыта форма письма и курсор не в поле ввода. Включаются и выключаются в Настройках → Горячие клавиши. Подсказка в самой почте — клавиша <kbd>?</kbd>.</p>
                        <article class="help__item">
                            <h3>Навигация</h3>
                            <table class="help__table help__keys">
                                <tr><td><kbd>j</kbd> <kbd>k</kbd> или <kbd>↓</kbd> <kbd>↑</kbd></td><td>следующее / предыдущее письмо</td></tr>
                                <tr><td><kbd>Enter</kbd> или <kbd>o</kbd></td><td>открыть</td></tr>
                                <tr><td><kbd>u</kbd></td><td>к списку</td></tr>
                                <tr><td><kbd>g</kbd> затем <kbd>i</kbd> / <kbd>s</kbd> / <kbd>d</kbd> / <kbd>a</kbd> / <kbd>t</kbd></td><td>Входящие / Отправленные / Черновики / Архив / Корзина</td></tr>
                                <tr><td><kbd>/</kbd></td><td>поиск</td></tr>
                            </table>
                        </article>
                        <article class="help__item">
                            <h3>Письмо</h3>
                            <table class="help__table help__keys">
                                <tr><td><kbd>r</kbd> <kbd>a</kbd> <kbd>f</kbd></td><td>ответить / ответить всем / переслать</td></tr>
                                <tr><td><kbd>e</kbd></td><td>архив</td></tr>
                                <tr><td><kbd>#</kbd> или <kbd>Delete</kbd></td><td>удалить</td></tr>
                                <tr><td><kbd>s</kbd></td><td>флажок</td></tr>
                                <tr><td><kbd>i</kbd></td><td>прочитано / непрочитано</td></tr>
                                <tr><td><kbd>z</kbd></td><td>отложить</td></tr>
                            </table>
                        </article>
                        <article class="help__item">
                            <h3>Разбор и написание</h3>
                            <table class="help__table help__keys">
                                <tr><td><kbd>v</kbd> <kbd>l</kbd> <kbd>!</kbd></td><td>в папку / метка / спам</td></tr>
                                <tr><td><kbd>x</kbd></td><td>выбрать письмо; <kbd>Esc</kbd> — снять выбор</td></tr>
                                <tr><td><kbd>c</kbd></td><td>новое письмо</td></tr>
                                <tr><td><kbd>Ctrl</kbd>+<kbd>Enter</kbd></td><td>отправить</td></tr>
                                <tr><td><kbd>Ctrl</kbd>+<kbd>S</kbd></td><td>сохранить черновик</td></tr>
                                <tr><td><kbd>Ctrl</kbd>+<kbd>B</kbd> / <kbd>I</kbd> / <kbd>U</kbd> / <kbd>K</kbd></td><td>жирный / курсив / подчёркнутый / ссылка</td></tr>
                                <tr><td><kbd>n</kbd> (в контактах)</td><td>новый контакт</td></tr>
                                <tr><td><kbd>c</kbd> <kbd>t</kbd> <kbd>d</kbd> <kbd>w</kbd> <kbd>m</kbd> <kbd>a</kbd> (в календаре)</td><td>событие / сегодня / день / неделя / месяц / повестка</td></tr>
                            </table>
                        </article>
                    </section>

                    <!-- ═══════════ 14. Цифры ═══════════ -->
                    <section id="limits" class="card mset__section help__section">
                        <h2>Ограничения и цифры</h2>
                        <article class="help__item">
                            <h3>Что и сколько</h3>
                            <table class="help__table">
                                <tr><td>Размер ящика</td><td>{{ limits.quotaMb ? `по умолчанию ${limits.quotaMb} МБ` : 'без ограничения' }}; ваш — внизу левой колонки. Меняет администратор.</td></tr>
                                <tr><td>Размер письма с вложениями</td><td>до {{ limits.sizeLimitMb }} МБ</td></tr>
                                <tr><td>Файлов в одном письме</td><td>до 20<template v-if="cloud.enabled">, через облако — до 256 МБ каждый, порог облака {{ cloud.thresholdMb }} МБ</template></td></tr>
                                <tr><td>Запрещённые вложения</td><td>{{ limits.blockedExt || 'exe, scr, bat, cmd, js, vbs, pif' }}</td></tr>
                                <tr><td>Получателей в письме</td><td>до {{ limits.maxRecipients }}</td></tr>
                                <tr v-if="throttleText"><td>Исходящих писем</td><td>{{ throttleText }} на сотрудника</td></tr>
                                <tr><td>Правил</td><td>до 50; в правиле до 10 условий и 6 действий</td></tr>
                                <tr><td>Быстрых ответов</td><td>до 8</td></tr>
                                <tr><td>Паролей приложений</td><td>до 10</td></tr>
                                <tr><td>Фото контакта</td><td>до 1,5 МБ; файл импорта — до 10 МБ</td></tr>
                                <tr><td>Карантин</td><td>хранится {{ quarantine.keepDays }} дней</td></tr>
                                <tr><td>Писем на странице</td><td>40</td></tr>
                                <tr><td>Автосохранение черновика</td><td>каждые 30 секунд</td></tr>
                                <tr><td>Проверка новых писем</td><td>каждые 20 секунд (в фоновой вкладке — раз в минуту)</td></tr>
                                <tr><td>Блокировка входа</td><td>15 минут после 8 неверных паролей</td></tr>
                            </table>
                        </article>
                    </section>

                    <!-- ═══════════ 15. Проблемы ═══════════ -->
                    <section id="trouble" class="card mset__section help__section">
                        <h2>Если что-то не так</h2>
                        <article class="help__item">
                            <h3>Письмо не отправляется</h3>
                            <p>Посмотрите текст ошибки в плашке внизу: «Укажите получателя», «Неверный адрес», «больше N МБ». Если письмо ушло, а потом вернулось письмом от «Mail Delivery System» — читайте причину в нём: «User unknown» — нет такого адреса, «Quota exceeded» — ящик получателя полон, «blocked» или «spam» — сервер получателя отверг письмо (сообщите администратору, он проверит репутацию). Если письма застревают в «Ждут отправки» с пометкой «ошибка» — тоже к администратору.</p>
                        </article>
                        <article class="help__item">
                            <h3>Веб-почта «зависла» или показывает старое</h3>
                            <p>Нажмите «Обновить» над списком или перезагрузите страницу (<kbd>F5</kbd>). Если ошибка повторяется, выйдите и войдите заново. Сообщая администратору, назовите время, что делали и текст ошибки — так он найдёт запись в журнале.</p>
                        </article>
                        <article class="help__item">
                            <h3>Телефон перестал получать почту</h3>
                            <p>Чаще всего — сменился пароль (обновите его на телефоне или создайте пароль приложения), отозван пароль приложения, включена двухфакторная защита (телефону нужен пароль приложения) или заполнен ящик. Проверьте «Последние входы» в Настройках → Безопасность: там видно, что именно отвергнуто.</p>
                        </article>
                        <article class="help__item">
                            <h3>Пропала папка или письма</h3>
                            <p>Проверьте, не сработало ли правило (Настройки → Правила), не переложил ли письма коллега с правами редактора на вашу папку, и «Корзину». Папка могла «схлопнуться» в почтовой программе — в веб-почте всё показано как есть на сервере. Удалённое окончательно восстанавливается только из резервной копии через администратора.</p>
                        </article>
                        <article class="help__item">
                            <h3>Что решает только администратор</h3>
                            <p>Пароль от почты, размер ящика, дополнительные адреса и пересылки, доступ к общим ящикам отделов, общие книги контактов и календарь компании, требование двухфакторной защиты и её сброс, включение и время сводки карантина, общие правила спама для всех, список запрещённых вложений, лимиты на отправку, подключение облака для больших файлов, рассылки на группы адресов.</p>
                        </article>
                        <article class="help__item">
                            <h3>Как сообщать о проблеме</h3>
                            <p>Напишите администратору: ваш адрес, дата и время, что делали, точный текст ошибки (или снимок экрана), адрес отправителя/получателя и тема, если речь о конкретном письме. С этим он найдёт письмо в журнале сервера за минуту.</p>
                        </article>
                    </section>
                </div>
            </div>
        </div>
    </MailLayout>
</template>
